cypress_script:
describe('Test Case Listing Functionality', () => {
  it('should display the test cases page with the correct title and headings', () => {
    cy.visit('https://automationexercise.com/test_cases');
    cy.title().should('include', 'Automation Practice Website for UI Testing - Test Cases');
    cy.get('h2').contains('Test Cases').should('be.visible');
    cy.get('h2').contains('Subscription').should('be.visible');
  });
  it('should not navigate away when clicking on a test case link without expanding', () => {
    cy.visit('https://automationexercise.com/test_cases');
    cy.get('a').contains('Test Case 1: Register User').click();
    cy.url().should('eq', 'https://automationexercise.com/test_cases');
    cy.get('#collapse1').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Test Case Listing Functionality', () => {
  test('should display the test cases page with the correct title and headings', async ({ page }) => {
    await page.goto('https://automationexercise.com/test_cases');
    await expect(page).toHaveTitle(/Automation Practice Website for UI Testing - Test Cases/);
    await expect(page.locator('h2').withText('Test Cases')).toBeVisible();
    await expect(page.locator('h2').withText('Subscription')).toBeVisible();
  });
  test('should not navigate away when clicking on a test case link without expanding', async ({ page }) => {
    await page.goto('https://automationexercise.com/test_cases');
    await page.click('a:has-text("Test Case 1: Register User")');
    await expect(page).toHaveURL('https://automationexercise.com/test_cases');
    await expect(page.locator('#collapse1')).toBeVisible();
  });
});
